"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["30459"],{99202(e){e.exports=JSON.parse('{"id":"FIN-455","slug":"freemium-model","term":"Freemium Model","also_known_as":[],"difficulty":"Beginner","definition":"A freemium model is a business model in which a basic version of a product or service is offered free of charge, while customers pay for premium features, extra capacity or an advertising-free experience.","explanation":["The idea is to attract a large number of users with a free offering, then persuade some of them to pay for more. The name combines \\"free\\" and \\"premium\\".","Freemium is common in software, mobile apps, online games, cloud storage and music streaming. For example, a cloud storage service might offer 5 gigabytes free and charge a monthly fee for 1 terabyte, or a music app might offer free listening with adverts and charge for an ad-free version.","The model works when the cost of serving free users is low and the free version is good enough to attract users but limited enough to encourage upgrades. Usually, only a small percentage of free users become paying customers. If a service has 1 million free users and 3% upgrade at 10 a month, it earns 300,000 a month.","Free users can still provide value through advertising revenue, word-of-mouth promotion or network effects. The challenge is striking the right balance: too generous a free version reduces upgrades, while too limited a version fails to attract users in the first place."],"note":"","total":1500,"prev":{"slug":"free-trade","term":"Free Trade"},"next":{"slug":"frictional-unemployment","term":"Frictional Unemployment"}}')}}]);